function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();const options={signal:controller.signal};const tools=[{name:'get_pdf_workspace',title:'Inspect PDF workspace',description:'Read the current document name, page count, selected page, and unsaved-change state. Does not expose document contents.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({filename,pages:meta?.count||0,currentPage:page+1,unsavedChanges:!!dirty()})},{name:'navigate_pdf_page',title:'Go to PDF page',description:'Navigate to a page of the open PDF. Page numbers start at 1.',inputSchema:{type:'object',properties:{page:{type:'integer',minimum:1}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!Number.isInteger(input.page)||!meta||input.page<1||input.page>meta.count||editing||busy)throw Error('Choose an existing page and finish any active edit first.');await goPage(input.page-1);return {page:page+1};}},{name:'start_pdf_text_editing',title:'Select text editing tool',description:'Activate the visible Edit text tool so the user can choose a line on the page. Does not change PDF content.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async()=>{if(!meta||editing||busy)throw Error('Open a PDF and finish any active edit first.');await chooseTool('edit');return {tool,ready:true};}}];for(const tool of tools)Promise.resolve(context.registerTool(tool,options)).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
safe(async()=>{setLoading(true,'Opening your workspace…');updateMeta(await rpc('demo'));await renderPage();refreshThumbnails();setLoading(false);registerTools();})();
